Kept this version direct. For every requested index, the loop checks all positions after it and increases the count when the value is strictly larger. It is easy to follow and does not change `arr`.

```cpp
#include <vector>
using namespace std;

class Solution {
public:
    vector<int> count_NGE(vector<int> &arr, vector<int> &indices) {
        vector<int> answer;

        for (int index : indices) {
            int greaterCount = 0;
            for (int j = index + 1; j < arr.size(); ++j) {
                if (arr[j] > arr[index]) {
                    ++greaterCount;
                }
            }
            answer.push_back(greaterCount);
        }

        return answer;
    }
};
```

Time complexity: `O(q * n)`, where `q` is the number of queries.
Space complexity: `O(q)` for the returned list.

I first compress the values so they can be used as positions in a Fenwick tree. Scanning from right to left means the tree contains exactly the elements to the right of the current value.

The tree can tell how many seen values are less than or equal to the current value. Subtracting that from the number of seen values leaves the number that are strictly greater. For a dry run on `[3, 1, 4]`, when `3` is processed, the tree contains `1` and `4`; one value is greater, so its count becomes `1`.

```cpp
#include <algorithm>
#include <vector>
using namespace std;

class Solution {
public:
    vector<int> count_NGE(vector<int> &arr, vector<int> &indices) {
        int n = arr.size();
        vector<int> sortedValues = arr;
        sort(sortedValues.begin(), sortedValues.end());
        sortedValues.erase(unique(sortedValues.begin(), sortedValues.end()),
                           sortedValues.end());

        vector<int> tree(n + 1, 0);
        vector<int> countAtIndex(n, 0);
        int seen = 0;

        auto add = [&](int position) {
            while (position <= n) {
                ++tree[position];
                position += position & -position;
            }
        };

        auto prefixSum = [&](int position) {
            int total = 0;
            while (position > 0) {
                total += tree[position];
                position -= position & -position;
            }
            return total;
        };

        for (int i = n - 1; i >= 0; --i) {
            int rank = lower_bound(sortedValues.begin(), sortedValues.end(), arr[i])
                       - sortedValues.begin() + 1;
            int lessOrEqual = prefixSum(rank);
            countAtIndex[i] = seen - lessOrEqual;
            add(rank);
            ++seen;
        }

        vector<int> answer;
        for (int index : indices) {
            answer.push_back(countAtIndex[index]);
        }
        return answer;
    }
};
```

Time complexity: `O((n + q) log n)` after sorting the values.
Space complexity: `O(n)` for the compressed values, tree, and saved counts.

This one handles each query separately. The part after the requested index is copied, sorted, and searched with an upper-bound binary search. Using `upperBound` skips all values equal to `arr[index]`, which keeps the comparison strictly greater.

An index at the last position gets an empty range, so its result is zero. The input array is left as it is.

```java
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    public List<Integer> count_NGE(int[] arr, int[] indices) {
        List<Integer> answer = new ArrayList<>();

        for (int index : indices) {
            int length = arr.length - index - 1;
            int[] rightPart = new int[length];
            System.arraycopy(arr, index + 1, rightPart, 0, length);
            Arrays.sort(rightPart);

            int firstGreater = upperBound(rightPart, arr[index]);
            answer.add(length - firstGreater);
        }

        return answer;
    }

    private int upperBound(int[] values, int target) {
        int left = 0;
        int right = values.length;

        while (left < right) {
            int middle = left + (right - left) / 2;
            if (values[middle] <= target) {
                left = middle + 1;
            } else {
                right = middle;
            }
        }

        return left;
    }
}
```

Time complexity: `O(q * n log n)` in the worst case.
Space complexity: `O(n)` for the temporary sorted part of one query.

## Intuition
Since the problem is very similar to counting inversions, we can use a modified merge sort that, during the merge, counts how many elements on the right are greater than the current element.

## Approach
1. Create a Pairs array to retain the original element - index relation.
2. Run the merge sort for the above-created pairs array.
3. In the merging step, as the recursion applies a stack structure, the right side of the array will be sorted and consist of larger elements; hence, we will compare: if at any point the left element < right element, we can say that all the elements from the current right element to the end of the right array will be greater than the left element. Hence, increment the count for the original index of the left element by high - right + 1.

## Solution
```java[]
class Pair {
    int val;
    int ind;

    Pair(int val, int ind) {
        this.val = val;
        this.ind = ind;
    }
}

class Solution {

    private void merge(Pair[] pairs, int low, int mid, int high, int[] count) {

        Pair[] temp = new Pair[high - low + 1];

        int left = low;
        int right = mid + 1;
        int idx = 0;


        while (left <= mid && right <= high) {
            if (pairs[left].val < pairs[right].val) {
                count[pairs[left].ind] += high - right + 1;
                temp[idx] = pairs[left];
                left++;
            } else {
                temp[idx] = pairs[right];
                right++;
            }
            idx++;
        }

        while (left <= mid) {
            temp[idx++] = pairs[left++];
        }

        while (right <= high) {
            temp[idx++] = pairs[right++];
        }

        for (int i = low; i <= high; i++, idx++) {
            pairs[i] = temp[i - low];
        }
    }

    private void mergeSort(Pair[] pairs, int low, int high, int[] count) {
        if (low >= high) {
            return;
        }

        int mid = low + (high - low) / 2;
        mergeSort(pairs, low, mid, count);
        mergeSort(pairs, mid + 1, high, count);
        merge(pairs, low, mid, high, count);
    }


    public List<Integer> count_NGE(int[] arr, int[] indices) {
        // Your code goes here

        Pair[] pairs = new Pair[arr.length];
        int[] count = new int[arr.length];

        for (int i = 0; i < arr.length; i++) {
            pairs[i] = new Pair(arr[i], i);
        }

        mergeSort(pairs, 0, arr.length - 1, count);

        List<Integer> res = new ArrayList<>();

        for (int i = 0; i < indices.length; i++) {
            res.add(count[indices[i]]);
        }

        return res;
    }
}
```

## Complexity
**Time Complexity:**
O(N) - for constructing the pairs array
O(N log N) - for the merge sort
O(Q) - for constructing the result list

**Space Complexity:**
O(2N) - for the pairs array
O(N) - for the count array
O(N) - for the recursion stack
O(N) - for the temp array used for the sorting
O(Q) - for the output list

## Intuition
To solve this efficiently, we need a time complexity of $O(N \log N)$. The standard way to count "how many items are smaller/greater than $X$ in a dynamic set" is to iterate through the array from right to left while building a Binary Indexed Tree (BIT) or a Segment Tree.

## Approach
1. Coordinate Compression: Since the numbers in arr can be very large or negative, we map them to ranks (1, 2, 3...) based on their sorted order.

2. Right-to-Left Traversal: We iterate backwards. For each number, we ask the BIT: "How many numbers have I seen so far that are less than or equal to my current rank?"

3. Calculate Greater: Since we know the total numbers we've seen so far, Total Seen - Less Or Equal = Strictly Greater.

4. Update: We then add our current number to the BIT so the elements to our left can count it.

## Solution
```java[]
import java.util.*;

class Solution {
    public List<Integer> count_NGE(int[] arr, int[] indices) {
        int n = arr.length;
        List<Integer> result = new ArrayList<>();

        // 1. Coordinate Compression
        // This maps values to their relative rank (1, 2, 3...) 
        // to keep the BIT array size manageable.
        int[] sortedArr = arr.clone();
        Arrays.sort(sortedArr);

        Map<Integer, Integer> ranks = new HashMap<>();
        int rank = 1;
        for (int num : sortedArr) {
            if (!ranks.containsKey(num)) {
                ranks.put(num, rank++);
            }
        }

        // 2. Precalculate the counts for ALL positions
        // We go right-to-left to see what's already to the "right"
        int[] precalculated = new int[n];
        BIT bit = new BIT(rank); 

        for (int i = n - 1; i >= 0; i--) {
            int currentRank = ranks.get(arr[i]);
            int totalElementsToRight = (n - 1) - i;

            // Numbers strictly greater = Total processed - (Numbers <= current)
            int lessOrEqual = bit.query(currentRank);
            precalculated[i] = totalElementsToRight - lessOrEqual;

            // Add this number to the "seen" pool in the BIT
            bit.update(currentRank, 1);
        }

        // 3. Build the final list based on the requested indices
        for (int idx : indices) {
            result.add(precalculated[idx]);
        }

        return result;
    }

    // Standard BIT/Fenwick Tree
    class BIT {
        int[] tree;
        public BIT(int size) {
            tree = new int[size + 1];
        }
        public void update(int i, int delta) {
            for (; i < tree.length; i += i & -i) tree[i] += delta;
        }
        public int query(int i) {
            int sum = 0;
            for (; i > 0; i -= i & -i) sum += tree[i];
            return sum;
        }
    }
}
```

## Complexity
**Time Complexity:** 
$O(N \log N)$ for sorting the array, plus $O(N \log N)$ for doing the BIT queries/updates

**Space Complexity:**
$O(N)$ for the BIT, Rank Map, and precalculated array

